void adl_serializer<tgbot::ChatId>::to_json(json& j, const tgbot::ChatId& value) {
    std::visit([&j](const auto& alt) { j = alt; }, value);
}
void adl_serializer<tgbot::ChatId>::from_json(const json& j, tgbot::ChatId& value) {
    if (j.is_string()) {
        value = j.get<std::string>();
    } else {
        value = j.get<std::int64_t>();
    }
}

void adl_serializer<tgbot::InputPollMedia>::to_json(json& j, const tgbot::InputPollMedia& value) {
    std::visit([&j](const auto& alt) { j = alt; }, value);
}
void adl_serializer<tgbot::InputPollMedia>::from_json(const json& j, tgbot::InputPollMedia& value) {
    const auto& d = j.at("type").get_ref<const std::string&>();
    if (d == "animation") {
        value = j.get<tgbot::InputMediaAnimation>();
    } else if (d == "audio") {
        value = j.get<tgbot::InputMediaAudio>();
    } else if (d == "document") {
        value = j.get<tgbot::InputMediaDocument>();
    } else if (d == "live_photo") {
        value = j.get<tgbot::InputMediaLivePhoto>();
    } else if (d == "location") {
        value = j.get<tgbot::InputMediaLocation>();
    } else if (d == "photo") {
        value = j.get<tgbot::InputMediaPhoto>();
    } else if (d == "venue") {
        value = j.get<tgbot::InputMediaVenue>();
    } else if (d == "video") {
        value = j.get<tgbot::InputMediaVideo>();
    } else {
        throw tgbot::Error("unknown InputPollMedia type: " + d);
    }
}

